    private readonly Button _login = new() { Text = "Login / Load" }, _preview = new() { Text = "Preview" }, _commit = new() { Text = "Commit Draft" }, _clear = new() { Text = "Clear" }, _edit = new() { Text = "Edit Selected" };
    private readonly WinFormsTimer _timer = new() { Interval = 120 }; private readonly UIA3Automation _automation = new();
    private readonly List<CapturedItem> _items = []; private FlaUIElement? _last; private string? _lastValue; private bool _wasDown; private string? _token;
    [DllImport("user32.dll")] static extern bool GetCursorPos(out POINT p); [DllImport("user32.dll")] static extern short GetAsyncKeyState(int key); [StructLayout(LayoutKind.Sequential)] struct POINT { public int X; public int Y; }
    record CapturedItem(int StepNo,string EventType,string Action,string? TestData,string ExpectedResult,string ScreenCode,string ObjectCode,string ObjectName,string ControlType,string? AutomationId,string SelectorJson,bool Sensitive=false);
    public CaptureForm(string? hubUrl = null, string? username = null, string? password = null)
    {
        Text = "ProMaxx2 Capture Companion"; Width = 1100; Height = 720; MinimumSize = new Size(900, 600); StartPosition = FormStartPosition.CenterScreen; BackColor = Color.FromArgb(246, 248, 251); Font = new Font("Segoe UI", 10F); _url.Text = string.IsNullOrWhiteSpace(hubUrl) ? _url.Text : hubUrl; _user.Text = username ?? string.Empty; _password.Text = password ?? string.Empty; _password.UseSystemPasswordChar = true; _app.Items.AddRange(["pos", "app"]); _app.SelectedIndex = 0;
        foreach (var c in new[] { _project, _module, _testCase, _app }) c.DropDownStyle = ComboBoxStyle.DropDownList;
        foreach (var c in new Control[] { _url, _user, _password }) c.Margin = new Padding(4, 5, 8, 5);
        foreach (var c in new ComboBox[] { _project, _module, _testCase, _app }) { c.Margin = new Padding(4, 5, 8, 5); c.IntegralHeight = false; c.DropDownHeight = 260; }
        _hover.BackColor = Color.White; _hover.BorderStyle = BorderStyle.FixedSingle; _hover.Padding = new Padding(18); _hover.Font = new Font("Segoe UI", 11F);
        _events.BackColor = Color.White; _events.BorderStyle = BorderStyle.FixedSingle; _events.HorizontalScrollbar = true;
        StyleButton(_login, Color.FromArgb(37, 99, 235), Color.White); StyleButton(_preview, Color.FromArgb(226, 232, 240), Color.FromArgb(30, 41, 59)); StyleButton(_commit, Color.FromArgb(22, 163, 74), Color.White); StyleButton(_edit, Color.FromArgb(226, 232, 240), Color.FromArgb(30, 41, 59)); StyleButton(_clear, Color.FromArgb(254, 226, 226), Color.FromArgb(153, 27, 27));
        _project.FormattingEnabled = _module.FormattingEnabled = _testCase.FormattingEnabled = true;
        _project.Format += (_, e) => e.Value = FormatItem(e.ListItem, "projectCode", "projectName");
        _module.Format += (_, e) => e.Value = FormatItem(e.ListItem, "moduleCode", "moduleName");
        _testCase.Format += (_, e) => e.Value = FormatItem(e.ListItem, "testCaseCode", "title");
        var top = new TableLayoutPanel { Dock = DockStyle.Top, Height = 166, ColumnCount = 6, RowCount = 3, Padding = new Padding(18, 12, 18, 10), BackColor = Color.White }; for (var i=0;i<6;i++) top.ColumnStyles.Add(i%2==0?new ColumnStyle(SizeType.Absolute,90):new ColumnStyle(SizeType.Percent,25));
        Add(top,"Hub URL",_url,0,0,5); Add(top,"User",_user,0,1,1); Add(top,"Password",_password,2,1,1); Add(top,"Application",_app,0,2,1); Add(top,"Project",_project,2,2,1); top.Controls.Add(_login,4,1);
        var scope = new FlowLayoutPanel { Dock = DockStyle.Top, Height = 58, Padding = new Padding(18, 8, 18, 8), BackColor = Color.FromArgb(241, 245, 249), WrapContents = false }; scope.Controls.Add(new Label{Text="Module",AutoSize=true,Padding=new Padding(0,8,5,0)}); scope.Controls.Add(_module); scope.Controls.Add(new Label{Text="Test Case",AutoSize=true,Padding=new Padding(14,8,5,0)}); scope.Controls.Add(_testCase); _preview.Enabled=false; _commit.Enabled=false; scope.Controls.Add(_edit); scope.Controls.Add(_clear); scope.Controls.Add(_preview); scope.Controls.Add(_commit);
        var split = new SplitContainer { Dock = DockStyle.Fill, Padding = new Padding(18, 14, 18, 18), BackColor = Color.FromArgb(246, 248, 251) }; split.Panel1.Padding = new Padding(0, 28, 8, 0); split.Panel2.Padding = new Padding(8, 28, 0, 0); split.Panel1.Controls.Add(_hover); split.Panel2.Controls.Add(_events); var leftTitle = new Label { Text = "UIA Control Detail", Dock = DockStyle.Top, Height = 28, Font = new Font("Segoe UI", 10F, FontStyle.Bold), ForeColor = Color.FromArgb(30, 41, 59) }; var rightTitle = new Label { Text = "Captured Steps", Dock = DockStyle.Top, Height = 28, Font = new Font("Segoe UI", 10F, FontStyle.Bold), ForeColor = Color.FromArgb(30, 41, 59) }; split.Panel1.Controls.Add(leftTitle); split.Panel2.Controls.Add(rightTitle); Controls.Add(split); Controls.Add(scope); Controls.Add(top); Shown += (_, _) => { split.Panel1MinSize = 180; split.Panel2MinSize = 180; split.SplitterDistance = Math.Max(180, Math.Min(split.ClientSize.Width / 2, split.ClientSize.Width - 180)); };
        _login.Click += async (_,_) => await LoadScopeAsync(); _project.SelectedIndexChanged += async (_,_) => await LoadProjectDataAsync(); _preview.Click += async (_,_) => await SendAsync(false); _commit.Click += async (_,_) => await SendAsync(true); _clear.Click += (_,_) => { _items.Clear(); _events.Items.Clear(); }; _edit.Click += (_,_) => EditSelected(); _timer.Tick += (_,_) => PollTarget(); _timer.Tick += (_,_) => PollText(); _timer.Start(); FormClosed += (_,_) => { _timer.Stop(); _automation.Dispose(); };
