    static void StyleButton(Button button, Color backColor, Color foreColor){button.AutoSize = true; button.FlatStyle = FlatStyle.Flat; button.FlatAppearance.BorderSize = 0; button.BackColor = backColor; button.ForeColor = foreColor; button.Font = new Font("Segoe UI", 9.5F, FontStyle.Bold); button.Padding = new Padding(10, 4, 10, 4); button.Margin = new Padding(5, 5, 5, 5);}
    static void Add(TableLayoutPanel t,string label,Control c,int x,int y,int span){t.Controls.Add(new Label{Text=label,AutoSize=true,Padding=new Padding(0,7,4,0)},x,y);t.Controls.Add(c,x+1,y);t.SetColumnSpan(c,span);c.Dock=DockStyle.Fill;}
    async Task LoadScopeAsync(){try{using var h=Client();var r=await h.PostAsJsonAsync($"{_url.Text.TrimEnd('/')}/auth/login",new{username=_user.Text,password=_password.Text});r.EnsureSuccessStatusCode();var j=await r.Content.ReadFromJsonAsync<JsonElement>();_token=j.GetProperty("accessToken").GetString();await LoadAsync($"{_url.Text.TrimEnd('/')}/projects",_project);_preview.Enabled=_commit.Enabled=true;MessageBox.Show("Login สำเร็จ");}catch(Exception ex){MessageBox.Show($"Login/Load ไม่สำเร็จ: {ex.Message}");}}
    async Task LoadProjectDataAsync(){if(_project.SelectedItem is not JsonElement p)return;var id=p.GetProperty("projectId").GetGuid();await LoadAsync($"{_url.Text.TrimEnd('/')}/projects/{id}/modules",_module);await LoadAsync($"{_url.Text.TrimEnd('/')}/automation/capture/test-cases?projectId={id}",_testCase);}
    static string FormatItem(object? item, string codeProperty, string nameProperty){if(item is not JsonElement j)return item?.ToString()??string.Empty;var code=j.TryGetProperty(codeProperty,out var c)?c.GetString():null;var name=j.TryGetProperty(nameProperty,out var n)?n.GetString():null;return string.IsNullOrWhiteSpace(code)?name??string.Empty:$"{code} - {name}";}
    async Task LoadAsync(string url,ComboBox box){using var h=Client();var a=await h.GetFromJsonAsync<JsonElement[]>(url)??[];box.Items.Clear();foreach(var x in a)box.Items.Add(x);if(box.Items.Count>0)box.SelectedIndex=0;}
    HttpClient Client(){var h=new HttpClient(new HubRecoveryHandler()){Timeout=TimeSpan.FromSeconds(20)};if(!string.IsNullOrWhiteSpace(_token)){if(TokenExpired(_token)){_token=null;throw new InvalidOperationException("QA Hub session expired. Please login again.");}h.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",_token);}return h;}
    void PollTarget(){try{if(IsPromaxxForeground())Poll();}catch{} }
    static bool IsPromaxxForeground(){try{var handle=GetForegroundWindow();if(handle==IntPtr.Zero)return false;GetWindowThreadProcessId(handle,out var pid);var path=Process.GetProcessById((int)pid).MainModule?.FileName??"";return path.EndsWith("Promaxxs.App.exe",StringComparison.OrdinalIgnoreCase)||path.EndsWith("PromaxxsPos.exe",StringComparison.OrdinalIgnoreCase);}catch{return false;}}
    [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow(); [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr hWnd,out uint processId);
    static bool TokenExpired(string token){try{var part=token.Split('.')[1].Replace('-','+').Replace('_','/');part+=new string('=',(4-part.Length%4)%4);using var doc=JsonDocument.Parse(Convert.FromBase64String(part));return doc.RootElement.GetProperty("exp").GetInt64()<=DateTimeOffset.UtcNow.ToUnixTimeSeconds()+30;}catch{return false;}}
    void PollText(){if(_last is null||!_last.ControlType.ToString().Equals("Edit",StringComparison.OrdinalIgnoreCase))return;try{var value=_last.Patterns.Value.Pattern.Value;if(value==_lastValue)return;_lastValue=value;var sensitive=(_last.Name+" "+_last.AutomationId).Contains("password",StringComparison.OrdinalIgnoreCase)||_last.Properties.IsPassword.ValueOrDefault;var n=_items.Count+1;_items.Add(new(n,"TextInput",$"Enter text in {_last.Name}",sensitive?null:value,"ผู้ใช้ตรวจสอบผลลัพธ์หลังดำเนินการ","",$"OBJ_{n:000}",_last.Name,"Edit",_last.AutomationId,string.IsNullOrWhiteSpace(_last.AutomationId)?"{}":JsonSerializer.Serialize(new{automationId=_last.AutomationId}),sensitive));_events.Items.Add($"{n}. TEXT INPUT | {(sensitive?"[MASKED]":value)} | {_last.AutomationId ?? "Missing AutomationId"}");}catch{}}
    void Poll(){if(!GetCursorPos(out var p))return;FlaUIElement? e=null;try{e=_automation.FromPoint(new System.Drawing.Point(p.X,p.Y));}catch{}if(e is not null&&!ReferenceEquals(e,_last)){_last=e;_hover.Text=$"Name: {e.Name}\r\nAutomationId: {e.AutomationId}\r\nControlType: {e.ControlType}\r\nClass: {SafeClassName(e)}";}var d=(GetAsyncKeyState(1)&0x8000)!=0;if(d&&!_wasDown&&e is not null){var n=_items.Count+1;_items.Add(new(n,"Click",$"Click {e.Name}",null,"ผู้ใช้ตรวจสอบผลลัพธ์หลังดำเนินการ","",$"OBJ_{n:000}",e.Name,e.ControlType.ToString(),e.AutomationId,string.IsNullOrWhiteSpace(e.AutomationId)?"{}":JsonSerializer.Serialize(new{automationId=e.AutomationId})));_events.Items.Add($"{n}. CLICK | {e.AutomationId ?? "Missing AutomationId"} | {e.Name}");}_wasDown=d;}
    static string SafeClassName(FlaUIElement element){try{return element.ClassName;}catch{return "(ไม่รองรับโดย Control นี้)";}}
    async Task SendAsync(bool commit){try{if(_project.SelectedItem is not JsonElement p||_module.SelectedItem is not JsonElement m||_testCase.SelectedItem is not JsonElement t)throw new InvalidOperationException("เลือก Project, Module และ Test Case ก่อน");var req=new{projectId=p.GetProperty("projectId").GetGuid(),moduleId=m.GetProperty("moduleId").GetGuid(),testCaseId=t.GetProperty("testCaseId").GetGuid(),applicationCode=_app.Text,sourceMachine=Environment.MachineName,applicationVersion=Application.ProductVersion,items=_items};using var h=Client();var r=await h.PostAsJsonAsync($"{_url.Text.TrimEnd('/')}/automation/capture/sessions",req);r.EnsureSuccessStatusCode();var s=await r.Content.ReadFromJsonAsync<JsonElement>();if(commit){var id=s.GetProperty("sessionId").GetGuid();var c=await h.PostAsync($"{_url.Text.TrimEnd('/')}/automation/capture/sessions/{id}/commit",null);c.EnsureSuccessStatusCode();MessageBox.Show("Commit Draft สำเร็จ");}else MessageBox.Show("Preview สำเร็จ");}catch(Exception ex){MessageBox.Show($"ส่ง Capture ไม่สำเร็จ: {ex.Message}");}}
